def word_count_ascii(text: str) -> list:
    words = []
    current = []
    for ch in text:
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z'):
            if 'A' <= ch <= 'Z':
                current.append(chr(ord(ch) + 32))
            else:
                current.append(ch)
        else:
            if current:
                words.append(''.join(current))
                current.clear()
    if current:
        words.append(''.join(current))
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    result = [[w, counts[w]] for w in counts]
    result.sort()
    return result
```

